 98→export async function runAgentLoop(
 99→  message: string,
100→  agentSessionId: string | null,
101→  langfuseSessionId: string | null,
102→  conversationHistory: { role: string; content: string }[] | null,
103→  callbacks: AgentCallbacks,
104→  signal?: AbortSignal,
105→  userSessionId?: string,
106→): Promise<void> {
107→  try {
108→    const response = await fetch('/api/chat', {
109→      method: 'POST',
110→      headers: {
111→        'Content-Type': 'application/json',
112→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
113→      },
114→      body: JSON.stringify({
115→        message,
116→        session_id: agentSessionId,
117→        langfuse_session_id: langfuseSessionId,
118→        conversation_history: conversationHistory ?? [],
119→      }),
120→      signal,
121→    });
122→
123→    if (!response.ok) {
124→      const errorText = await response.text();
125→      callbacks.onError(`Server error: ${errorText}`);
126→      return;
127→    }
128→
129→    await streamSSE(response, callbacks, signal);
130→  } catch (e: unknown) {
131→    if (signal?.aborted) return;
132→    const msg = e instanceof Error ? e.message : 'Connection failed';
133→    callbacks.onError(msg);
134→  }
135→}
