137→export async function runAgentEditLoop(
138→  newMessage: string,
139→  conversationHistory: { role: string; content: string }[],
140→  langfuseSessionId: string | null,
141→  callbacks: AgentCallbacks,
142→  signal?: AbortSignal,
143→  userSessionId?: string,
144→): Promise<void> {
145→  try {
146→    const response = await fetch('/api/chat/edit', {
147→      method: 'POST',
148→      headers: {
149→        'Content-Type': 'application/json',
150→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
151→      },
152→      body: JSON.stringify({
153→        new_message: newMessage,
154→        conversation_history: conversationHistory,
155→        langfuse_session_id: langfuseSessionId,
156→      }),
157→      signal,
158→    });
159→
160→    if (!response.ok) {
161→      const errorText = await response.text();
162→      callbacks.onError(`Server error: ${errorText}`);
163→      return;
164→    }
165→
166→    await streamSSE(response, callbacks, signal);
167→  } catch (e: unknown) {
168→    if (signal?.aborted) return;
169→    const msg = e instanceof Error ? e.message : 'Connection failed';
170→    callbacks.onError(msg);
171→  }
172→}
