450→            setIsStreaming(false);
451→            abortRef.current = null;
452→          },
453→        },
454→        controller.signal,
455→        userSessionId,
456→      );
457→    },
458→    [isStreaming, messages, flushText, refreshTables, userSessionId]
459→  );
460→
461→  const deleteMessage = useCallback(
462→    (messageIndex: number) => {
463→      if (isStreaming) return;
464→
465→      // Store remaining messages as history for Langfuse context on next send
466→      setMessages((prev) => {
467→        const remaining = prev.slice(0, messageIndex);
468→        pendingHistoryRef.current = remaining
469→          .filter((m) => m.role === 'user' || m.role === 'assistant')
470→          .map((m) => ({ role: m.role, content: m.content }));
471→        return remaining;
472→      });
473→
474→      // Clear session so next message starts fresh
475→      sessionIdRef.current = null;
476→    },
477→    [isStreaming]
478→  );
479→
480→  const clearMessages = useCallback(() => {
481→    if (abortRef.current) {
482→      abortRef.current.abort();
483→    }
484→    setMessages([]);
485→    setIsStreaming(false);
486→    sessionIdRef.current = null;
487→    pendingHistoryRef.current = null;
488→  }, []);
489→
490→  return (
491→    <AgentContext.Provider
492→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages }}
493→    >
494→      {children}
495→    </AgentContext.Provider>
496→  );
497→}
