 21→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 22→  // Use streaming remainder if available
 23→  if (streamingRemainder?.trim()) {
 24→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 25→    const last = lines[lines.length - 1] || '';
 26→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 27→  }
 28→  // Otherwise use last thinking segment's last line
 29→  for (let i = segments.length - 1; i >= 0; i--) {
 30→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 31→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 32→      const last = lines[lines.length - 1] || '';
 33→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 34→    }
 35→  }
 36→  return t('thinking');
 37→}
 38→
 39→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming }: {
 40→  segments: ContentSegment[];
 41→  streamingRemainder?: string;
 42→  isThinkingPhase: boolean;
 43→  isAgentStreaming: boolean;
 44→}) {
 45→  const { t } = useTranslation();
 46→  // All non-answer, non-chart segments go inside the thinking block
 47→  const thinkingSegments = segments.filter(
 48→    (s) => s.type !== 'answer' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && s.chart_spec)
 49→  );
 50→  const hasContent = thinkingSegments.some(
 51→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start'
 52→  ) || streamingRemainder?.trim();
 53→
 54→  if (!hasContent) return null;
 55→
 56→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 57→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 58→
 59→  return (
 60→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 61→      <summary className="message-bubble__collapsible-summary">
 62→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 63→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 64→      </summary>
 65→      <div className="message-bubble__thinking-body">
 66→        {thinkingSegments.map((seg, i) => {
 67→          if (seg.type === 'thinking' && seg.text?.trim()) {
 68→            return (
 69→              <div key={i} className="message-bubble__segment-content">
 70→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 71→              </div>
 72→            );
 73→          }
 74→          if (seg.type === 'tool' && seg.toolResult) {
 75→            return (
 76→              <div key={i} className="message-bubble__tool-segment">
 77→                <InlineQueryResult result={seg.toolResult} />
 78→              </div>
 79→            );
 80→          }
 81→          if (seg.type === 'subagent_start') {
 82→            const displayName = seg.subagentName === 'sql-analyst'
 83→              ? t('sqlAnalystWorking')
 84→              : seg.subagentName === 'chart-builder'
 85→              ? t('chartBuilderWorking')
 86→              : `${seg.subagentName} working...`;
 87→            return (
 88→              <div key={i} className="message-bubble__subagent-indicator">
 89→                <span className="message-bubble__subagent-label">{displayName}</span>
 90→              </div>
 91→            );
 92→          }
 93→          return null;
 94→        })}
 95→        {streamingRemainder?.trim() && (
 96→          <div className="message-bubble__segment-content">
 97→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
 98→          </div>
 99→        )}
100→      </div>
101→    </details>
102→  );
103→}
