105→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
106→  const { t } = useTranslation();
107→  const { isStreaming, editMessage, deleteMessage } = useAgent();
108→  const [isEditing, setIsEditing] = useState(false);
109→  const [editText, setEditText] = useState(message.content);
110→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
111→  const textareaRef = useRef<HTMLTextAreaElement>(null);
112→
113→  const isUser = message.role === 'user';
114→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
115→
116→  useEffect(() => {
117→    if (isEditing && textareaRef.current) {
118→      textareaRef.current.focus();
119→      textareaRef.current.selectionStart = textareaRef.current.value.length;
120→    }
121→  }, [isEditing]);
122→
123→  const handleEdit = () => {
124→    setEditText(message.content);
125→    setIsEditing(true);
126→    setIsConfirmingDelete(false);
127→  };
128→
129→  const handleCancelEdit = () => {
130→    setIsEditing(false);
131→    setEditText(message.content);
132→  };
133→
134→  const handleSaveEdit = () => {
135→    const trimmed = editText.trim();
136→    if (!trimmed || trimmed === message.content) {
137→      handleCancelEdit();
138→      return;
139→    }
140→    setIsEditing(false);
141→    editMessage(messageIndex, trimmed);
142→  };
143→
144→  const handleDeleteConfirm = () => {
145→    setIsConfirmingDelete(false);
146→    deleteMessage(messageIndex);
147→  };
148→
149→  const handleKeyDown = (e: React.KeyboardEvent) => {
150→    if (e.key === 'Escape') {
151→      handleCancelEdit();
152→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
153→      e.preventDefault();
154→      handleSaveEdit();
155→    }
156→  };
157→
158→  let streamingRemainder: string | undefined;
159→  if (hasSegments && message.isStreaming && message.content) {
160→    const segmentedText = message.segments!
161→      .filter((s) => s.type !== 'tool')
162→      .map((s) => s.text || '')
163→      .join('');
164→    const remaining = message.content.slice(segmentedText.length);
165→    if (remaining.trim()) {
166→      streamingRemainder = remaining;
167→    }
168→  }
169→
170→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
171→  const isInAnswerPhase = message.currentPhase === 'answer';
172→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
173→
174→  const hasCharts = hasSegments && message.segments!.some(
175→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
176→  );
177→
178→  const answerSegments = hasSegments
179→    ? message.segments!
180→        .filter((s) => s.type === 'answer' && s.text?.trim())
181→        .map((s) => hasCharts ? { ...s, text: stripChartSpecBlocks(s.text!) } : s)
182→        .filter((s) => s.text?.trim())
183→    : [];
184→
185→  const chartSegments = hasSegments
186→    ? message.segments!.filter(
187→        (s) =>
188→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
189→          (s.type === 'subagent_end' && s.chart_spec)
190→      )
191→    : [];
192→
193→  return (
194→    <div className={`message-bubble message-bubble--${message.role}`}>
195→      <div className="message-bubble__header">
196→        {isUser ? t('you') : t('assistant')}
197→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
198→          <span className="message-bubble__actions">
199→            <button
200→              className="message-bubble__action-btn"
201→              onClick={handleEdit}
202→              title={t('editMessage')}
203→            >
204→              &#9998;
205→            </button>
206→            <button
207→              className="message-bubble__action-btn message-bubble__action-btn--delete"
208→              onClick={() => setIsConfirmingDelete(true)}
209→              title={t('deleteMessage')}
210→            >
211→              &#128465;
212→            </button>
213→          </span>
214→        )}
215→      </div>
216→
217→      {isUser && isConfirmingDelete && (
218→        <div className="message-bubble__confirm-delete">
219→          <span>{t('deleteConfirm')}</span>
220→          <div className="message-bubble__confirm-actions">
221→            <button
222→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
223→              onClick={handleDeleteConfirm}
224→            >
225→              {t('delete')}
226→            </button>
227→            <button
228→              className="message-bubble__confirm-btn"
229→              onClick={() => setIsConfirmingDelete(false)}
230→            >
231→              {t('cancel')}
232→            </button>
233→          </div>
234→        </div>
235→      )}
236→
237→      {isUser && isEditing ? (
238→        <div className="message-bubble__edit-mode">
239→          <textarea
240→            ref={textareaRef}
241→            className="message-bubble__edit-textarea"
242→            value={editText}
243→            onChange={(e) => setEditText(e.target.value)}
244→            onKeyDown={handleKeyDown}
245→            rows={3}
246→          />
247→          <div className="message-bubble__edit-actions">
248→            <button
249→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
250→              onClick={handleSaveEdit}
251→            >
252→              {t('saveResend')}
253→            </button>
254→            <button
255→              className="message-bubble__edit-btn"
256→              onClick={handleCancelEdit}
257→            >
258→              {t('cancel')}
259→            </button>
260→          </div>
261→        </div>
262→      ) : hasSegments ? (
263→        <div className="message-bubble__segments">
264→          <ThinkingBlock
265→            segments={message.segments!}
266→            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
267→            isThinkingPhase={isThinkingPhase}
268→            isAgentStreaming={!!message.isStreaming}
269→          />
270→          {(chartSegments.length > 0 || answerSegments.length > 0) && (
271→            <div className="message-bubble__segment message-bubble__segment--answer">
272→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
273→              {chartSegments.map((seg, i) => (
274→                <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
275→                  {seg.type === 'tool' && seg.toolResult ? (
276→                    <InlineQueryResult result={seg.toolResult!} />
277→                  ) : seg.chart_spec ? (
278→                    <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} />
279→                  ) : null}
280→                </div>
281→              ))}
282→              {answerSegments.map((seg, i) => (
283→                <div key={`answer-${i}`} className="message-bubble__segment-content">
284→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
285→                </div>
286→              ))}
287→            </div>
288→          )}
289→          {isInAnswerPhase && !hasAnswer && streamingRemainder?.trim() && (() => {
290→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
291→            return displayText?.trim() ? (
292→              <div className="message-bubble__segment message-bubble__segment--answer">
293→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
294→                <div className="message-bubble__segment-content">
295→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
296→                </div>
297→              </div>
298→            ) : null;
299→          })()}
300→          {message.isStreaming && !message.content && (
301→            <span className="message-bubble__typing">{t('thinking')}</span>
302→          )}
303→        </div>
304→      ) : (
305→        <>
306→          <div className="message-bubble__content">
307→            {message.content ? (
308→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
309→            ) : message.isStreaming ? (
310→              <span className="message-bubble__typing">{t('thinking')}</span>
311→            ) : null}
312→          </div>
313→          {message.toolCalls && message.toolCalls.length > 0 && (
314→            <div className="message-bubble__tools">
315→              {message.toolCalls.map((tc) => (
316→                <InlineQueryResult key={tc.toolCallId} result={tc} />
317→              ))}
318→            </div>
319→          )}
320→        </>
321→      )}
322→    </div>
323→  );
324→}
