185→            });
186→            setMessages((prev) =>
187→              prev.map((m) =>
188→                m.id === assistantId
189→                  ? { ...m, segments: [...segmentsRef.current] }
190→                  : m
191→              )
192→            );
193→          },
194→          onSubagentEnd: (data) => {
195→            segmentsRef.current.push({
196→              type: 'subagent_end',
197→              subagentId: data.id,
198→              subagentName: data.name,
199→              chart_spec: data.chart_spec,
200→              text: data.result,
201→            });
202→            setMessages((prev) =>
203→              prev.map((m) =>
204→                m.id === assistantId
205→                  ? { ...m, segments: [...segmentsRef.current] }
206→                  : m
207→              )
208→            );
209→          },
210→          onDone: (newSessionId) => {
211→            if (newSessionId) sessionIdRef.current = newSessionId;
212→            if (flushTimerRef.current) {
213→              clearTimeout(flushTimerRef.current);
214→              flushTimerRef.current = null;
215→            }
216→            flushText();
217→            if (currentTextRef.current.trim()) {
218→              segmentsRef.current.push({
219→                type: 'answer',
220→                text: currentTextRef.current,
